import { useEffect, useMemo, useState } from 'react';
import {
  ModalForm,
  PageContainer,
  ProColumns,
  ProFormText,
  ProFormSwitch,
  ProTable,
} from '@ant-design/pro-components';
import { Button, Popconfirm, Switch, message } from 'antd';
import type { ColumnsType } from 'antd/es/table';

import {
  Tenant,
  TenantPayload,
  createTenant,
  deleteTenant,
  listTenants,
  updateTenant,
} from '@/services/tenant';

const toErrorMessage = (error: unknown): string => {
  const e = error as
    | { data?: { detail?: string }; info?: { errorMessage?: string }; message?: string }
    | undefined;
  return e?.data?.detail || e?.info?.errorMessage || e?.message || '请求失败，请稍后重试';
};

const TenantPage = () => {
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [rows, setRows] = useState<Tenant[]>([]);
  const [query, setQuery] = useState<Record<string, any>>({});
  const [editing, setEditing] = useState<Tenant | null>(null);

  const loadRows = async () => {
    setLoading(true);
    try {
      setRows(await listTenants());
    } catch (error) {
      message.error(toErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRows();
  }, []);

  const filteredRows = useMemo(() => {
    const norm = (v: unknown) => String(v ?? '').trim().toLowerCase();
    return rows.filter((row) => {
      if (query.code && !norm(row.code).includes(norm(query.code))) {
        return false;
      }
      if (query.name && !norm(row.name).includes(norm(query.name))) {
        return false;
      }
      if (query.host && !norm(row.host).includes(norm(query.host))) {
        return false;
      }
      return true;
    });
  }, [query, rows]);

  const columns: ProColumns<Tenant>[] = [
    {
      title: '序号',
      valueType: 'indexBorder',
      width: 68,
      hideInSearch: true,
      fixed: 'left',
    },
    {
      title: '编码',
      dataIndex: 'code',
      width: 120,
    },
    {
      title: '名称',
      dataIndex: 'name',
      width: 200,
    },
    {
      title: '域名',
      dataIndex: 'host',
      width: 200,
    },
    {
      title: '状态',
      dataIndex: 'active',
      width: 80,
      valueType: 'select',
      valueEnum: {
        true: { text: '启用', status: 'Success' },
        false: { text: '停用', status: 'Error' },
      },
      render: (_, row) => (
        <Switch
          checked={row.active}
          checkedChildren="启用"
          unCheckedChildren="停用"
          onChange={async (checked) => {
            try {
              await updateTenant(row.id, { active: checked });
              message.success('更新成功');
              await loadRows();
            } catch (error) {
              message.error(toErrorMessage(error));
            }
          }}
        />
      ),
    },
    {
      title: '操作',
      valueType: 'option',
      width: 160,
      render: (_, row) => [
        <Button
          key="edit"
          type="link"
          onClick={() => {
            setEditing(row);
            setModalOpen(true);
          }}
        >
          编辑
        </Button>,
        <Popconfirm
          key="delete"
          title="确认删除该租户吗？"
          onConfirm={async () => {
            try {
              await deleteTenant(row.id);
              message.success('删除成功');
              await loadRows();
            } catch (error) {
              message.error(toErrorMessage(error));
            }
          }}
        >
          <Button danger type="link">
            删除
          </Button>
        </Popconfirm>,
      ],
    },
  ];

  return (
    <PageContainer
      title="租户管理"
      subTitle="管理系统中的所有租户"
    >
      <ProTable<Tenant>
        rowKey="id"
        loading={loading}
        columns={columns}
        dataSource={filteredRows}
        scroll={{ x: 800 }}
        search={{ labelWidth: 'auto' }}
        onSubmit={(values) => setQuery(values)}
        onReset={() => setQuery({})}
        options={{ reload: loadRows }}
        toolBarRender={() => [
          <Button
            key="create"
            type="primary"
            onClick={() => {
              setEditing(null);
              setModalOpen(true);
            }}
          >
            新建租户
          </Button>,
        ]}
      />

      <ModalForm<TenantPayload>
        title={editing ? '编辑租户' : '新建租户'}
        open={modalOpen}
        modalProps={{
          destroyOnHidden: true,
          onCancel: () => {
            setModalOpen(false);
            setEditing(null);
          },
        }}
        submitter={{
          submitButtonProps: { loading: saving },
          searchConfig: { submitText: '保存' },
        }}
        initialValues={
          editing
            ? {
                code: editing.code,
                name: editing.name,
                host: editing.host,
                active: editing.active,
              }
            : { active: true }
        }
        onFinish={async (values) => {
          setSaving(true);
          try {
            const payload: TenantPayload = {
              code: values.code.trim(),
              name: values.name.trim(),
              host: values.host.trim(),
              active: values.active,
            };

            if (editing) {
              await updateTenant(editing.id, payload);
              message.success('更新成功');
            } else {
              await createTenant(payload);
              message.success('创建成功');
            }
            setModalOpen(false);
            setEditing(null);
            await loadRows();
            return true;
          } catch (error) {
            message.error(toErrorMessage(error));
            return false;
          } finally {
            setSaving(false);
          }
        }}
      >
        <ProFormText
          name="code"
          label="编码"
          rules={[
            { required: true, message: '请输入租户编码' },
            { max: 12, message: '编码最多12个字符' },
          ]}
        />
        <ProFormText
          name="name"
          label="名称"
          rules={[
            { required: true, message: '请输入租户名称' },
            { max: 64, message: '名称最多64个字符' },
          ]}
        />
        <ProFormText
          name="host"
          label="域名"
          rules={[
            { required: true, message: '请输入域名' },
            { max: 255, message: '域名最多255个字符' },
          ]}
        />
        <ProFormSwitch name="active" label="状态" />
      </ModalForm>
    </PageContainer>
  );
};

export default TenantPage;

