import { useEffect, useMemo, useState } from 'react';
import {
  ModalForm,
  PageContainer,
  ProColumns,
  ProFormDigit,
  ProFormSelect,
  ProFormText,
  ProFormTextArea,
  ProTable,
} from '@ant-design/pro-components';
import { Button, Popconfirm, Switch, Tag, message } from 'antd';

import {
  Sensor,
  SensorPayload,
  createSensor,
  deleteSensor,
  listSensors,
  updateSensor,
} from '@/services/sensor';

const toErrorMessage = (error: unknown): string => {
  const e = error as
    | { data?: { detail?: string }; info?: { errorMessage?: string }; message?: string }
    | undefined;
  return e?.data?.detail || e?.info?.errorMessage || e?.message || '请求失败，请稍后重试';
};

const SensorProductPage = () => {
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [rows, setRows] = useState<Sensor[]>([]);
  const [query, setQuery] = useState<Record<string, any>>({});
  const [editing, setEditing] = useState<Sensor | null>(null);

  const loadRows = async () => {
    setLoading(true);
    try {
      setRows(await listSensors());
    } catch (error) {
      message.error(toErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRows();
  }, []);

  const filteredRows = useMemo(() => {
    const norm = (v: unknown) => String(v ?? '').trim().toLowerCase();
    return rows.filter((row) => {
      if (query.sn && !norm(row.sn).includes(norm(query.sn))) {
        return false;
      }
      return true;
    });
  }, [query, rows]);

  const columns: ProColumns<Sensor>[] = [
    {
      title: '序号',
      valueType: 'indexBorder',
      width: 68,
      hideInSearch: true,
      fixed: 'left',
    },
    {
      title: '序列号',
      dataIndex: 'sn',
      width: 200,
    },
    {
      title: '电量(%)',
      dataIndex: 'battery',
      width: 100,
      valueType: 'digit',
      hideInSearch: true,
      render: (_, row) => {
        const val = Number(row.battery);
        const color = val > 50 ? 'green' : val > 20 ? 'orange' : 'red';
        return <Tag color={color}>{val}%</Tag>;
      },
    },
    {
      title: '状态',
      dataIndex: 'active',
      width: 80,
      valueType: 'select',
      valueEnum: {
        true: { text: '在线', status: 'Success' },
        false: { text: '离线', status: 'Default' },
      },
      render: (_, row) => (
        <Switch
          checked={row.active}
          checkedChildren="在线"
          unCheckedChildren="离线"
          onChange={async (checked) => {
            try {
              await updateSensor(row.id, { active: checked });
              message.success('更新成功');
              await loadRows();
            } catch (error) {
              message.error(toErrorMessage(error));
            }
          }}
        />
      ),
    },
    {
      title: '描述',
      dataIndex: 'description',
      ellipsis: true,
      hideInSearch: true,
      render: (_, row) => row.description || '-',
    },
    {
      title: '激活时间',
      dataIndex: 'active_at',
      width: 180,
      valueType: 'dateTime',
      hideInSearch: true,
    },
    {
      title: '创建时间',
      dataIndex: 'created_at',
      width: 180,
      valueType: 'dateTime',
      hideInSearch: true,
    },
    {
      title: '操作',
      valueType: 'option',
      width: 160,
      render: (_, row) => [
        <Button
          key="edit"
          type="link"
          onClick={() => {
            setEditing(row);
            setModalOpen(true);
          }}
        >
          编辑
        </Button>,
        <Popconfirm
          key="delete"
          title="确认删除该传感器吗？"
          onConfirm={async () => {
            try {
              await deleteSensor(row.id);
              message.success('删除成功');
              await loadRows();
            } catch (error) {
              message.error(toErrorMessage(error));
            }
          }}
        >
          <Button danger type="link">
            删除
          </Button>
        </Popconfirm>,
      ],
    },
  ];

  return (
    <PageContainer
      title="传感器产品管理"
      subTitle="管理所有传感器产品"
    >
      <ProTable<Sensor>
        rowKey="id"
        loading={loading}
        columns={columns}
        dataSource={filteredRows}
        scroll={{ x: 1100 }}
        search={{ labelWidth: 'auto' }}
        onSubmit={(values) => setQuery(values)}
        onReset={() => setQuery({})}
        options={{ reload: loadRows }}
        toolBarRender={() => [
          <Button
            key="create"
            type="primary"
            onClick={() => {
              setEditing(null);
              setModalOpen(true);
            }}
          >
            新建传感器
          </Button>,
        ]}
      />

      <ModalForm<SensorPayload>
        title={editing ? '编辑传感器' : '新建传感器'}
        open={modalOpen}
        modalProps={{
          destroyOnHidden: true,
          onCancel: () => {
            setModalOpen(false);
            setEditing(null);
          },
        }}
        submitter={{
          submitButtonProps: { loading: saving },
          searchConfig: { submitText: '保存' },
        }}
        initialValues={
          editing
            ? {
                sn: editing.sn,
                description: editing.description,
                battery: editing.battery,
                active: editing.active,
                sensor_type_id: editing.sensor_type_id,
              }
            : { battery: 100, active: true }
        }
        onFinish={async (values) => {
          setSaving(true);
          try {
            const payload: SensorPayload = {
              sn: values.sn.trim(),
              description: values.description?.trim(),
              battery: Number(values.battery ?? 100),
              active: values.active,
              sensor_type_id: values.sensor_type_id,
            };

            if (editing) {
              await updateSensor(editing.id, payload);
              message.success('更新成功');
            } else {
              await createSensor(payload);
              message.success('创建成功');
            }
            setModalOpen(false);
            setEditing(null);
            await loadRows();
            return true;
          } catch (error) {
            message.error(toErrorMessage(error));
            return false;
          } finally {
            setSaving(false);
          }
        }}
      >
        <ProFormText
          name="sn"
          label="序列号"
          rules={[
            { required: true, message: '请输入传感器序列号' },
            { max: 255, message: '序列号最多255个字符' },
          ]}
        />
        <ProFormTextArea
          name="description"
          label="描述"
        />
        <ProFormDigit
          name="battery"
          label="电量(%)"
          min={0}
          max={100}
          fieldProps={{ precision: 1 }}
        />
        <ProFormSelect
          name="active"
          label="状态"
          options={[
            { label: '在线', value: true },
            { label: '离线', value: false },
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
      </ModalForm>
    </PageContainer>
  );
};

export default SensorProductPage;
